using System;
using System.IO;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

var build = BinaryLog.ReadBuild("build.binlog");

// Get all diagnostic messages from compilation
Console.WriteLine("=== ALL DIAGNOSTICS (errors + key messages) ===");
build.VisitAllChildren<AbstractDiagnostic>(d => {
    var proj = "";
    var parent = d.Parent;
    while (parent != null) {
        if (parent is Project p) { proj = Path.GetFileName(p.ProjectFile ?? ""); break; }
        parent = (parent as TreeNode)?.Parent as BaseNode;
    }
    Console.WriteLine($"[{proj}] {d.GetType().Name}: {d.ToString()}");
});

// Check for "did not compile" type messages
Console.WriteLine("\n=== KEY MESSAGES ===");
build.VisitAllChildren<Message>(m => {
    if (m.Text != null && (m.Text.Contains("Models.cs") || m.Text.Contains("UserService") || m.Text.Contains("Program.cs")))
        Console.WriteLine($"  {m.Text.Substring(0, Math.Min(m.Text.Length, 200))}");
});
EOF
